% Heatmap of the percentage of displacement vectors per range of the
% dominant displacement component (um) and dominant direction. This heatmap
% was used to define the limits of the filtering step (0.3-8 um).
%
% Input: tp_01.mat file(s) generated by TFMLAB, in the folder defined in dataFolder.
% Output: heatmap (displacement_magnitude_direction.png / .pdf).

clear
clc
close all

%% Input (edit the path)
dataFolder = 'path/to/D_2_displacements/beads';
files = dir(fullfile(dataFolder, 'tp_01.mat'));

%% Magnitude bins (last bin collects everything above 20)
edges  = [0 0.61 1:20 Inf];
nBins  = length(edges) - 1;

%% Directions: 1=+X, 2=-X, 3=+Y, 4=-Y, 5=+Z, 6=-Z
counts = zeros(nBins, 6);

%% Process files
for k = 1:numel(files)
    fprintf('Processing %s\n', files(k).name)
    S = load(fullfile(files(k).folder, files(k).name));
    X = S.dispField.X(:);
    Y = S.dispField.Y(:);
    Z = S.dispField.Z(:);

    % remove NaNs
    valid = ~(isnan(X) | isnan(Y) | isnan(Z));
    X = X(valid);
    Y = Y(valid);
    Z = Z(valid);

    % dominant direction (vectorized); compMag is the magnitude of the
    % dominant component, i.e. |X| for +-X, |Y| for +-Y, |Z| for +-Z
    [compMag, idx] = max(abs([X Y Z]), [], 2);
    dirIdx = zeros(size(idx));
    dirIdx(idx == 1 & X >= 0) = 1;
    dirIdx(idx == 1 & X <  0) = 2;
    dirIdx(idx == 2 & Y >= 0) = 3;
    dirIdx(idx == 2 & Y <  0) = 4;
    dirIdx(idx == 3 & Z >= 0) = 5;
    dirIdx(idx == 3 & Z <  0) = 6;

    % magnitude bin based on the component magnitude (bins are [left, right),
    % the last one is [20, Inf))
    bin = discretize(compMag, edges);

    % accumulate counts
    counts = counts + accumarray([bin dirIdx], 1, [nBins 6]);
end

%% Conversion to percentage of all valid displacements
totalDisp = sum(counts(:));
pct = 100 * counts / totalDisp;
fprintf('Total valid displacements: N = %d\n', totalDisp)

%% Labels
binLabels = cell(nBins, 1);
for i = 1:nBins-1
    binLabels{i} = sprintf('%.2f-%.2f', edges(i), edges(i+1));
end
binLabels{nBins} = sprintf('>%d', edges(end-1));
dirLabels = {'+X','-X','+Y','-Y','+Z','-Z'};

%% Figure (size in cm, to match text width)
fig = figure('Color','w', 'Units','centimeters', 'Position',[2 2 12 14]);
ax = axes(fig);
imagesc(ax, pct)

% white-to-blue colormap (light enough for black cell labels)
cLow  = [1.00 1.00 1.00];
cHigh = [0.45 0.62 0.80];
colormap(ax, [linspace(cLow(1),cHigh(1),256)', ...
              linspace(cLow(2),cHigh(2),256)', ...
              linspace(cLow(3),cHigh(3),256)'])

% colorbar with title
cb = colorbar(ax);
ylabel(cb, 'Displacement vectors (%)', 'FontName','Arial', 'FontSize',8)

% axes
xticks(ax, 1:6);       xticklabels(ax, dirLabels)
yticks(ax, 1:nBins);   yticklabels(ax, binLabels)
xlabel(ax, 'Dominant displacement direction')
ylabel(ax, 'Displacement magnitude range (\mum)')
set(ax, 'FontName','Arial', 'FontSize',8, 'TickDir','out', 'Box','off')

% values inside the cells, with % symbol
[cc, rr] = meshgrid(1:6, 1:nBins);
text(ax, cc(:), rr(:), compose('%.1f%%', pct(:)), ...
    'HorizontalAlignment','center', 'FontName','Arial', ...
    'FontSize',7, 'Color','k')

%% Export
exportgraphics(fig, 'displacement_magnitude_direction.png', 'Resolution', 300)
exportgraphics(fig, 'displacement_magnitude_direction.pdf', 'ContentType','vector')
